// Browser test of the Documents admin page against the local test server (port 4100).
import { createRequire } from "node:module";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const puppeteer = createRequire(path.join(here, "browser", "x.js"))("puppeteer-core");
const OUT = path.join(here, "out");
fs.mkdirSync(OUT, { recursive: true });
const BASE = "http://localhost:4100";
let failures = 0;
const check = (name, cond, extra) => {
  console.log(`${cond ? "PASS" : "FAIL"}  ${name}${!cond && extra !== undefined ? `  -> ${JSON.stringify(extra)}` : ""}`);
  if (!cond) failures++;
};

const browser = await puppeteer.launch({ executablePath: "C:/Program Files/Google/Chrome/Application/chrome.exe", headless: true, args: ["--no-first-run"] });
const page = await browser.newPage();
await page.setViewport({ width: 1366, height: 900 });
const errors = [];
page.on("pageerror", (e) => errors.push(e.message));
page.on("console", (m) => m.type() === "error" && errors.push(m.text()));
// window.print would open a dialog; record the call instead.
await page.evaluateOnNewDocument(() => {
  window.__prints = 0;
  window.print = () => window.__prints++;
});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function clickText(selector, text, { within } = {}) {
  const handle = await page.waitForFunction(
    (sel, t, w) => [...(w ? document.querySelector(w) : document).querySelectorAll(sel)].find((el) => el.textContent.trim().startsWith(t) && el.offsetParent !== null),
    { timeout: 8000 },
    selector,
    text,
    within ?? null,
  );
  await handle.asElement().click();
  await sleep(400);
}
const text = () => page.evaluate(() => document.body.innerText);
const shot = (name) => page.screenshot({ path: path.join(OUT, `${name}.png`), fullPage: true });
const stock = (variantId) =>
  page.evaluate(async (id) => (await (await fetch("/api/admin/inventory", { credentials: "include" })).json()).find((v) => v.variantId === id).available, variantId);

async function printToPdf(name) {
  await page.waitForFunction(() => window.__prints > 0 && document.querySelector("#admin-print"), { timeout: 8000 });
  await page.emulateMediaType("print");
  await page.pdf({ path: path.join(OUT, `${name}.pdf`), preferCSSPageSize: true, printBackground: true });
  await page.emulateMediaType("screen");
  await page.evaluate(() => {
    window.__prints = 0;
    window.dispatchEvent(new Event("afterprint"));
  });
  await sleep(300);
}

// --- login
await page.goto(`${BASE}/system/login`, { waitUntil: "networkidle0" });
await page.type("#username", "admin");
await page.type("#password", "admin123");
await page.click("button[type=submit]");
await page.waitForNavigation({ waitUntil: "networkidle0" }).catch(() => {});

// --- menu item + list
await page.goto(`${BASE}/system/documents?type=quotation`, { waitUntil: "networkidle0" });
check("menu shows Quotations & Invoices", (await text()).includes("Quotations & Invoices"));
check("quotation list shows Q101 invoiced", (await text()).includes("2026-Q101") && (await text()).includes("Invoiced 2026-026"));
await shot("1-quotations-desktop");

// --- new quotation via form: picking a saved client fills the address
await clickText("button", "New quotation");
await page.type("#billToName", "Badan Pengurusan Bersama Residensi Wangsamas");
await sleep(200);
const addr = await page.$eval("#billToAddress", (el) => el.value);
check("known client fills address", addr.includes("Wangsa Delima"), addr);
const validUntil = await page.$eval("#validUntil", (el) => el.value);
check("valid until defaults to +30 days", validUntil === (() => { const d = new Date(); d.setDate(d.getDate() + 30); return d.toLocaleDateString("en-CA"); })(), validUntil);
await page.select("#doc-form select", "1");
await page.evaluate(() => {
  const set = (el, v) => {
    Object.getOwnPropertyDescriptor(Object.getPrototypeOf(el), "value").set.call(el, v);
    el.dispatchEvent(new Event("input", { bubbles: true }));
  };
  const inputs = [...document.querySelectorAll("#doc-form input[type=number]")];
  set(inputs.at(-2), "200");
  set(inputs.at(-1), "4.80");
  set(document.querySelector("#doc-form input[placeholder^='e.g. Warranty']"), "(Warranty 1 year upon delivery date)");
});
await sleep(200);
check("form total updates (200 × 4.80)", (await text()).includes("RM 960.00") || (await text()).includes("RM960.00"));
await shot("2-quotation-form-desktop");
await clickText("button", "Create");
await page.waitForFunction(() => document.body.innerText.includes("Created quotation 2026-Q102"), { timeout: 8000 }).catch(() => {});
check("quotation Q102 created from the form", (await text()).includes("Created quotation 2026-Q102"));

// --- print quotation
await page.evaluate(() => {
  const row = [...document.querySelectorAll("tbody tr")].find((r) => r.innerText.includes("2026-Q102"));
  row.querySelector("button[aria-label=Print]").click();
});
await printToPdf("quotation-2026-Q102");

// --- website order -> invoice
await page.goto(`${BASE}/system/orders/pending`, { waitUntil: "networkidle0" });
await clickText("button", "Invoice");
await page.waitForSelector("#doc-form", { timeout: 8000 });
check("order invoice form says copied from website order", (await text()).includes("Copied from website order"));
check("order invoice bill-to is the company", (await page.$eval("#billToName", (el) => el.value)) === "NSI Solutions Sdn Bhd");
await shot("3-order-invoice-form");
await clickText("button", "Create");
await page.waitForFunction(() => document.body.innerText.includes("Created invoice"), { timeout: 8000 }).catch(() => {});
const t = await text();
check("order invoice created as 2026-027, already paid, RM 137", t.includes("Created invoice 2026-028") || t.includes("Created invoice 2026-027"), t.slice(0, 400));
check("order invoice shows Paid", /Paid \d/.test(t));
await shot("4-invoices-desktop");

// Second click on the same order finds the existing invoice instead of making another.
await page.goto(`${BASE}/system/orders/pending`, { waitUntil: "networkidle0" });
await clickText("button", "Invoice");
await page.waitForFunction(() => document.body.innerText.includes("already has invoice"), { timeout: 8000 }).catch(() => {});
check("second Invoice click finds the existing invoice", (await text()).includes("already has invoice"));

// --- print the order invoice and the Excel-continued invoice 026
for (const no of ["2026-026"]) {
